USE acore_characters;
CREATE TABLE IF NOT EXISTS solazeroth_v3_marques_insignes SELECT guid, nombre FROM solazeroth_v3_collection WHERE objet = 910140;
INSERT INTO solazeroth_jetons_dus (account, jetons) SELECT c.account, SUM(i.nombre) FROM solazeroth_v3_marques_insignes i JOIN characters c ON c.guid = i.guid GROUP BY c.account ON DUPLICATE KEY UPDATE jetons = jetons + VALUES(jetons);
